from collections import deque

def bfs_at_depth(graph, start, target_depth):
    # BFS to find nodes at exactly target_depth
    # We don't return start node or intermediate depths

    # Queue contains (node, depth)
    queue = deque([(start, 0)])
    visited = {start}  # Track visited to avoid cycles

    nodes_at_target_depth = []

    while queue:
        node, depth = queue.popleft()

        # If we've reached target depth, add to result
        if depth == target_depth:
            nodes_at_target_depth.append(node)
            # Don't expand further from this node
            continue

        # If we're beyond target depth, skip
        if depth > target_depth:
            continue

        # Expand neighbors
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, depth + 1))

    return nodes_at_target_depth

